function setNested(target, path, value) {
  const parts = path.split('.');
  let node = target;
  parts.forEach((part, index) => {
    if (index === parts.length - 1) node[part] = value;
    else node = node[part] ||= {};
  });
}

export function applyJournalUiTranslations(translations) {
  languages.forEach((language, languageIndex) => {
    const journalUi = {};
    rows.forEach((row) => setNested(journalUi, row[0], row[languageIndex + 1]));
    translations[language].translation.journal_ui = {
      ...(translations[language]?.translation?.journal_ui || {}),
      ...journalUi
    };
  });
  return translations;
}
